CREATE TABLE IF NOT EXISTS identity.users (id uuid PRIMARY KEY DEFAULT platform.uuid_v7(), email citext NOT NULL, display_name text NOT NULL, preferred_locale text NOT NULL DEFAULT 'fr', is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid NOT NULL, version integer NOT NULL DEFAULT 1, CONSTRAINT uq_users__email UNIQUE (email), CONSTRAINT ck_users__locale CHECK (preferred_locale IN ('fr','ar','en')));
CREATE TABLE IF NOT EXISTS identity.roles (id uuid PRIMARY KEY DEFAULT platform.uuid_v7(), role_code text NOT NULL, name_fr text NOT NULL, name_ar text NOT NULL, name_en text NOT NULL, description text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL, version integer NOT NULL DEFAULT 1, CONSTRAINT uq_roles__role_code UNIQUE (role_code));
CREATE TABLE IF NOT EXISTS identity.permissions (id uuid PRIMARY KEY DEFAULT platform.uuid_v7(), permission_code text NOT NULL, name_fr text NOT NULL, name_ar text NOT NULL, name_en text NOT NULL, description text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL, version integer NOT NULL DEFAULT 1, CONSTRAINT uq_permissions__permission_code UNIQUE (permission_code));
CREATE TABLE IF NOT EXISTS identity.role_permissions (role_id uuid NOT NULL REFERENCES identity.roles(id), permission_id uuid NOT NULL REFERENCES identity.permissions(id), CONSTRAINT pk_role_permissions PRIMARY KEY (role_id, permission_id));
CREATE TABLE IF NOT EXISTS identity.user_roles (user_id uuid NOT NULL REFERENCES identity.users(id), role_id uuid NOT NULL REFERENCES identity.roles(id), granted_at timestamptz NOT NULL DEFAULT now(), granted_by uuid NOT NULL, expires_at timestamptz, CONSTRAINT pk_user_roles PRIMARY KEY (user_id, role_id));
CREATE TABLE IF NOT EXISTS identity.sessions (id uuid PRIMARY KEY DEFAULT platform.uuid_v7(), user_id uuid NOT NULL REFERENCES identity.users(id), session_token_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, CONSTRAINT uq_sessions__token_hash UNIQUE (session_token_hash));
CREATE INDEX IF NOT EXISTS ix_user_roles__role_id ON identity.user_roles (role_id);
CREATE INDEX IF NOT EXISTS ix_role_permissions__permission_id ON identity.role_permissions (permission_id);
CREATE TABLE IF NOT EXISTS org.tenants (id uuid PRIMARY KEY DEFAULT platform.uuid_v7(), tenant_code text NOT NULL, name_fr text NOT NULL, name_ar text NOT NULL, name_en text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid NOT NULL, version integer NOT NULL DEFAULT 1, CONSTRAINT uq_tenants__tenant_code UNIQUE (tenant_code), CONSTRAINT ck_tenants__status CHECK (status IN ('active','suspended','archived')));
CREATE TABLE IF NOT EXISTS org.organizations (id uuid PRIMARY KEY DEFAULT platform.uuid_v7(), tenant_id uuid NOT NULL REFERENCES org.tenants(id), organization_code text NOT NULL, name_fr text NOT NULL, name_ar text NOT NULL, name_en text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid NOT NULL, version integer NOT NULL DEFAULT 1, CONSTRAINT uq_organizations__tenant_code UNIQUE (tenant_id, organization_code), CONSTRAINT ck_organizations__status CHECK (status IN ('active','suspended','archived')));
CREATE TABLE IF NOT EXISTS org.organizational_units (id uuid PRIMARY KEY DEFAULT platform.uuid_v7(), tenant_id uuid NOT NULL, organization_id uuid NOT NULL REFERENCES org.organizations(id), unit_code text NOT NULL, name_fr text NOT NULL, name_ar text NOT NULL, name_en text NOT NULL, parent_unit_id uuid REFERENCES org.organizational_units(id), created_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid NOT NULL, version integer NOT NULL DEFAULT 1, CONSTRAINT uq_units__organization_code UNIQUE (organization_id, unit_code));
CREATE TABLE IF NOT EXISTS org.memberships (id uuid PRIMARY KEY DEFAULT platform.uuid_v7(), tenant_id uuid NOT NULL, organization_id uuid NOT NULL REFERENCES org.organizations(id), user_id uuid NOT NULL, membership_status text NOT NULL DEFAULT 'active', role_code text NOT NULL, granted_at timestamptz NOT NULL DEFAULT now(), granted_by uuid NOT NULL, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid NOT NULL, version integer NOT NULL DEFAULT 1, CONSTRAINT uq_memberships__active_scope UNIQUE (tenant_id, organization_id, user_id), CONSTRAINT ck_memberships__status CHECK (membership_status IN ('active','suspended','expired')));
CREATE INDEX IF NOT EXISTS ix_organizations__tenant_id__status ON org.organizations (tenant_id, status);
CREATE INDEX IF NOT EXISTS ix_memberships__tenant_id__organization_id ON org.memberships (tenant_id, organization_id);
ALTER TABLE identity.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE org.organizations ENABLE ROW LEVEL SECURITY;
ALTER TABLE org.memberships ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS identity_users_tenant_context ON identity.users;
CREATE POLICY identity_users_tenant_context ON identity.users USING (current_setting('app.tenant_id', true) IS NOT NULL);
DROP POLICY IF EXISTS organizations_tenant_context ON org.organizations;
CREATE POLICY organizations_tenant_context ON org.organizations USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
DROP POLICY IF EXISTS memberships_tenant_org_context ON org.memberships;
CREATE POLICY memberships_tenant_org_context ON org.memberships USING (tenant_id = current_setting('app.tenant_id', true)::uuid AND organization_id = current_setting('app.organization_id', true)::uuid);
